using NUnit.Framework;
using LighthouseKeepers.Core.Progression;
namespace LighthouseKeepers.Tests.M3 {
 public sealed class DrownedTests {
  static SabotageState Traces()=>new(new NightScenario{faults=new[]{new NightFault{stationId="engine"},new NightFault{stationId="pipe"},new NightFault{stationId="radio"}}});
  [Test] public void NoAppearanceInTutorialOrFirstMinute(){var t=Traces();var d=new DrownedState(t,false);t.Warn(0,20);d.Tick(20,true,false,false);t.Broke(0,23);d.Tick(23,true,false,false);Assert.AreEqual(DrownedPhase.Dormant,d.Phase);t=Traces();d=new DrownedState(t,true);t.Warn(0,90);d.Tick(90,true,false,false);Assert.AreEqual(DrownedPhase.Dormant,d.Phase);}
  [Test] public void WarningPrecedesManifestationAndPowerReturnsForceRetreat(){var t=Traces();var d=new DrownedState(t,false);t.Warn(0,80);d.Tick(80,false,false,false);Assert.AreEqual(DrownedPhase.Warning,d.Phase);t.Broke(0,83);d.Tick(83.6,true,false,false);Assert.AreEqual(DrownedPhase.Manifest,d.Phase);d.Tick(84,false,false,false);Assert.AreEqual(DrownedPhase.Retreat,d.Phase);d.Tick(86,false,false,false);Assert.AreEqual(DrownedPhase.Dormant,d.Phase);}
  [Test] public void ReliefCancelsAndOldWarningsDoNotReplay(){var t=Traces();var d=new DrownedState(t,false);t.Warn(0,80);d.Tick(80,true,true,false);t.Completed("pipe",90);d.Tick(100,true,false,false);Assert.AreEqual(DrownedPhase.Dormant,d.Phase);t.Warn(1,101);d.Tick(101,true,false,false);d.Tick(102,true,true,false);Assert.AreEqual(DrownedPhase.Retreat,d.Phase);}
  [Test] public void FirstControlGraceDefersAppearanceUntilItIsSafe(){var t=Traces();var d=new DrownedState(t,false);t.Warn(0,80);d.Tick(80,true,false,false);t.Broke(0,83);d.Tick(83,true,false,false,true);d.Tick(120,true,false,false,true);Assert.AreEqual(DrownedPhase.Dormant,d.Phase);d.Tick(140,true,false,false);Assert.AreEqual(DrownedPhase.Warning,d.Phase);d.Tick(143,true,false,false);Assert.AreEqual(DrownedPhase.Manifest,d.Phase);}
  [Test] public void GuestCannotInventOrExtendAppearance(){var t=Traces();var h=new DrownedState(t,false);var g=new DrownedState(t,false){ReadOnly=true};t.Warn(0,80);h.Tick(80,true,false,false);t.Broke(0,83);h.Tick(83.6,true,false,false);Assert.True(g.Apply(h.Capture(),83.6));g.Tick(100,false,false,true);Assert.AreEqual(DrownedPhase.Manifest,g.Phase);var f=h.Capture();f.since=84;Assert.False(g.Apply(f,83.6));f=h.Capture();f.phase=9;Assert.False(g.Apply(f,83.6));}
  [Test] public void DarknessMakesWeatherWorseAndRetreatEasesIt(){var n=new NightScenario{stormBaseStage=1,peakStormAfterFraction=1};var t=new TensionDirector(n);t.Tick(80,520,600,.1f,.1f,true,100,false,true,0,false,DrownedPhase.Manifest);Assert.AreEqual(4,t.StormStage);Assert.AreEqual(TensionPhase.Sabotage,t.Phase);t.Tick(81,519,600,.1f,.1f,false,100,false,true,0,false,DrownedPhase.Retreat);Assert.AreEqual(1,t.StormStage);Assert.AreEqual(TensionPhase.Relief,t.Phase);}

  [Test] public void WarningWaitsForVisibleSpotAndGuestCannotMoveIt(){var t=Traces();var h=new DrownedState(t,false);t.Warn(0,80);t.Broke(0,83);h.Tick(83,true,false,false,false,false);h.Tick(90,true,false,false,false,false);Assert.AreEqual(DrownedPhase.Warning,h.Phase);Assert.True(h.SetAnchor(1,2,3.3f,1,180,90));h.Tick(90.1,true,false,false,false,true);Assert.AreEqual(DrownedPhase.Manifest,h.Phase);var g=new DrownedState(t,false){ReadOnly=true};Assert.True(g.Apply(h.Capture(),90.1));Assert.AreEqual(2,g.X);Assert.False(g.SetAnchor(2,0,0,0,0,90.1));var f=h.Capture();f.x=float.NaN;Assert.False(g.Apply(f,90.1));f=h.Capture();f.anchorAt=100;Assert.False(g.Apply(f,90.1));}
  [Test] public void ProceduralEffectsStayInsideGeometryBudget(){var assembly=System.Reflection.Assembly.Load("Assembly-CSharp");var rain=(UnityEngine.Mesh)assembly.GetType("LighthouseKeepers.WatchDemo.HeavyStormRain").GetMethod("BuildStreaks").Invoke(null,null);var body=(UnityEngine.Mesh)assembly.GetType("LighthouseKeepers.WatchDemo.DrownedAppearance").GetMethod("BuildMesh").Invoke(null,null);try{Assert.LessOrEqual(rain.triangles.Length/3,3200);Assert.LessOrEqual(body.triangles.Length/3,12000);Assert.True(rain.bounds.size.x>=32);foreach(var v in body.vertices)Assert.True(float.IsFinite(v.x)&&float.IsFinite(v.y)&&float.IsFinite(v.z));}finally{UnityEngine.Object.DestroyImmediate(rain);UnityEngine.Object.DestroyImmediate(body);}}
  [Test] public void BlackoutDrivesDrownedStormEvenBeforeAShipThreatens(){var type=System.Type.GetType("LighthouseKeepers.WatchDemo.WatchState, Assembly-CSharp",true);var s=System.Activator.CreateInstance(type,UnityEngine.Resources.Load<FiveNightCatalog>("M3Campaign").nights,2,UnityEngine.Resources.Load("S4Tuning"),UnityEngine.Resources.Load("S4M2Tuning"),UnityEngine.Resources.Load("ImmersionTuning"));object Call(string n,params object[] a)=>type.GetMethod(n).Invoke(s,a);Call("EngageWatch");Call("Tick",61d);var step=System.Enum.Parse(System.Type.GetType("LighthouseKeepers.WatchDemo.KeeperStep, Assembly-CSharp"),"Fuel");Call("OfferStationGrace",step);for(int i=0;i<40&&((DrownedState)type.GetProperty("Drowned").GetValue(s)).Phase!=DrownedPhase.Manifest;i++)Call("Tick",.1d);Assert.Greater((double)type.GetProperty("StationGraceRemaining").GetValue(s),0,"Danger grace stays active during harmless reveal");Assert.AreEqual(DrownedPhase.Manifest,((DrownedState)type.GetProperty("Drowned").GetValue(s)).Phase);Assert.AreEqual(0,(double)type.GetProperty("BeaconDarkLimit").GetValue(s));Assert.AreEqual(4,((TensionDirector)type.GetProperty("Tension").GetValue(s)).StormStage);}
 }
}
